<script setup>
import {ref,computed,watch,onMounted,nextTick} from 'vue'
import {useRoute} from 'vue-router'
import FundContribution from './FundContribution.vue'
import Chart from './Chart.vue'
import {api,fmt,colors,kindLabel,safeUrl,escape} from '../shared'
const props=defineProps({data:Object}),route=useRoute()
const chain=ref(route.query.chain||({fund_paper:'fund_paper',patent:'patent_tech',contribution:'paper_tech'})[route.query.tab]||'mixed'),scope=ref('ai'),limit=ref(20),summary=ref(null),summaryError=ref(''),graph=ref(null),loading=ref(false),error=ref(''),selected=ref(null),step=ref(0),chart=ref(null),graphShell=ref(null),allLabels=ref(false)
const section=ref(route.query.tab==='contribution'?'contribution':'evidence')
watch(()=>route.query.tab,v=>section.value=v==='contribution'?'contribution':'evidence')
watch(()=>route.query.chain,v=>{if(v){chain.value=v;section.value='evidence'}})
function explore(id){section.value='evidence';chain.value=id;nextTick(()=>graphShell.value?.scrollIntoView({block:'start',behavior:'smooth'}))}
const chainTabs=[['mixed','多链关系'],['fund_paper','基金—论文—技术'],['paper_tech','论文—技术'],['patent_tech','专利—技术'],['fund_patent','基金—专利—技术'],['paper_network','论文间方法关联']]
const typeLabels={...kindLabel,fund:'基金项目',paper:'论文',patent:'专利',tech_point:'技术主题',technology:'技术主题',tech:'技术主题',institution:'机构',company:'企业'}
const typeColor={fund:'#AE0D28',paper:'#2877B0',patent:'#278771',tech_point:'#8B63AA',technology:'#8B63AA',tech:'#8B63AA',institution:'#D18A23',company:'#D18A23'}
const fieldLabels={proj_no:'批准号',proj_school:'依托单位',proj_author:'项目负责人',title:'标题',name:'名称',project_id:'项目编号',project_no:'项目编号',fund_id:'基金编号',paper_id:'论文标识',year:'年份',authors:'作者',institution:'机构',applicant:'申请主体',patent_number:'专利号',namespace:'来源类别',term_id:'技术编号',definition:'技术定义',source_row:'来源行',row_number:'来源行',source:'来源',source_file:'来源文件',topic_id:'技术编号',scope:'筛选范围',url:'原文链接',region:'机构地域'}
let sequence=0,summarySeq=0
async function fetchGraph(){const seq=++sequence;loading.value=true;error.value='';graph.value=null;selected.value=null;try{const d=await api('/api/llm/graph?'+new URLSearchParams({chain:chain.value,scope:scope.value,limit:String(limit.value)}));if(seq===sequence){graph.value=d;const n=d.nodes?.find(n=>n.id===route.query.node);if(n)selected.value={kind:'node',item:n}}}catch(e){if(seq===sequence)error.value=e.message}finally{if(seq===sequence)loading.value=false}}
async function fetchSummary(){const seq=++summarySeq;summary.value=null;try{const value=await api('/api/llm/chain-summary?scope='+scope.value);if(seq===summarySeq){summary.value=value;summaryError.value=''}}catch(e){if(seq===summarySeq)summaryError.value=e.message}}
watch([chain,scope,limit],fetchGraph)
watch(scope,fetchSummary)
onMounted(()=>{fetchSummary();fetchGraph()})
const nodeTypes=computed(()=>[...new Set((graph.value?.nodes||[]).map(n=>n.type))])
const graphOption=computed(()=>({animationDurationUpdate:350,tooltip:{confine:true,formatter:p=>p.dataType==='edge'?escape(p.data.label||'关系'):escape(p.data.fullLabel||p.data.name)},legend:{top:0,data:nodeTypes.value.map(t=>typeLabels[t]||t),textStyle:{fontSize:14,color:'#3D4859'},icon:'circle',itemWidth:14,itemHeight:14},series:[{type:'graph',layout:'force',labelLayout:{hideOverlap:true},roam:true,draggable:true,focusNodeAdjacency:true,zoom:(graph.value?.nodes?.length||0)>80?.66:.85,force:{repulsion:160,edgeLength:[65,105],gravity:.18,friction:.65},left:65,right:65,top:85,bottom:65,categories:nodeTypes.value.map(t=>({name:typeLabels[t]||t,itemStyle:{color:typeColor[t]||'#64748b'}})),data:(graph.value?.nodes||[]).map(n=>({id:n.id,name:n.label,fullLabel:n.label,raw:n,category:nodeTypes.value.indexOf(n.type),symbolSize:['technology','tech_point','tech'].includes(n.type)?34:30,label:{show:allLabels.value||['technology','tech','tech_point'].includes(n.type)||chain.value==='paper_network',color:'#344154',fontSize:13,position:'bottom',formatter:p=>p.name.length>18?p.name.slice(0,16)+'…':p.name},itemStyle:{color:typeColor[n.type]||'#64748b',borderColor:'#fff',borderWidth:2},emphasis:{label:{show:true,fontSize:15,fontWeight:700},itemStyle:{shadowBlur:12,shadowColor:'#64748b66'}}})),links:(graph.value?.edges||[]).map(e=>({...e,raw:e,lineStyle:{color:e.kind==='source_project_id'?'#AE0D28':'#8d9aae',width:2,curveness:.12},label:{show:false},emphasis:{label:{show:true,fontSize:13,color:'#394355',formatter:()=>e.label}}})),edgeSymbol:['none','arrow'],edgeSymbolSize:[4,8],emphasis:{focus:'adjacency'},lineStyle:{opacity:.65}}]}))
function onSelect(p){selected.value=p.dataType==='edge'?{kind:'edge',item:p.data.raw}:{kind:'node',item:p.data.raw}}
const neighbors=computed(()=>selected.value?.kind==='node'?(graph.value?.edges||[]).filter(e=>e.source===selected.value.item.id||e.target===selected.value.item.id):[])
const nodeName=id=>graph.value?.nodes?.find(n=>n.id===id)?.label||id
const selectedFields=computed(()=>selected.value?.kind==='node'?Object.entries(selected.value.item.fields||{}).filter(([k,v])=>['批准号','依托单位','负责人','作者','机构','DOI','申请号','主IPC分类号','申请人','论文','作者（节选）','论文署名机构','技术组','技术编号','批准年','申请年','proj_no','proj_school','proj_author'].includes(k)&&v!==null&&v!==''&&v!==undefined):[])
const readableSource=s=>s&&!/^(?:\/|data\/|[A-Z]:\\)/.test(s)
function display(v){if(Array.isArray(v))return v.map(x=>typeof x==='object'?(x.name||x.label||JSON.stringify(x)):x).join(' · ');if(typeof v==='object')return JSON.stringify(v);return String(v)}
const selectedStep=computed(()=>summary.value?.pipeline?.[step.value])
const chainDescription=c=>({fund_paper:`项目编号关联成果论文 · ${fmt(c.triples||0)} 组基金—论文—技术组合`,paper_tech:'从论文标题、摘要连接技术主题',patent_tech:'从专利公开文本连接技术主题',fund_patent:'基金与专利成果关联研究'})[c.id]
const currentEdges=computed(()=>props.data.currentInventory?.counts.ai_fund_papers??props.data.study.contribution.source_metrics.fund_paper_edges)
const displayedChains=computed(()=>(summary.value?.chains||[]).map(c=>c.id==='fund_paper'?{...c,count:currentEdges.value}:c))
const processSteps=computed(()=>[
 {title:'多源汇聚',text:'基金项目、成果论文与专利资料汇入研究底座，保留来源与时间。',sourceLabel:'成果来源',source:'基金 · 论文 · 专利'},
 {title:'直接映射',text:'以原始项目编号连接基金与成果论文，形成资助关联。',sourceLabel:'已建关系',source:fmt(currentEdges.value)+' 条资助关联'},
 {title:'技术识别',text:'从题名、摘要及公开文本识别技术内容，形成主题候选关联。',sourceLabel:'识别依据',source:'共同词表 · 原文片段'},
 {title:'核对与汇流',text:'核对实体和文本依据，让多条成果链在共同技术主题中交汇。',sourceLabel:'探索入口',source:'交互证据图'},
 {title:'贡献研究',text:'结合成果、技术覆盖与引用，研究基金支撑范围及技术影响。',sourceLabel:'分析维度',source:'支撑范围 · 影响力度'}])
const pipelineDescriptions=['依据技术词典界定主题、关键词与研究范围。','按来源整理成果记录，归并标识并保留原始依据。','以项目编号连接基金与论文，以技术词表连接论文和专利。','核对原始文本、发表时间及署名信息，建立可追溯的关系。','沿技术脉络组织成果，联接企业、产品与政策研究。']
async function fullScreen(){if(!document.fullscreenElement)await graphShell.value?.requestFullscreen?.();else await document.exitFullscreen?.();await nextTick();chart.value?.resize()}
const activeTitle=computed(()=>chainTabs.find(c=>c[0]===chain.value)?.[1]||chain.value)
const scopeLabel=computed(()=>({llm:'LLM 明确命中',ai:'AI 宽口径',context:'前史 / 语境关联'})[scope.value])
</script>
<template><div class="page-heading"><div><h2>创新链证据与基金贡献</h2><p>连接基金成果、论文方法与专利技术，追溯基础研究的支撑作用。</p></div><router-link to="/evolution" class="button secondary">技术演进 →</router-link></div><div class="evidence-page-tabs"><button :class="{active:section==='evidence'}" @click="section='evidence'">多链证据探索</button><button :class="{active:section==='contribution'}" @click="section='contribution'">基金贡献度</button></div><div v-if="section==='contribution'" key="contribution" class="pane-swap"><FundContribution :data="data" @explore="explore"/></div><div v-else key="evidence" class="pane-swap"><div v-if="summaryError" class="notice error">{{summaryError}} <button @click="fetchSummary">重试</button></div><div v-if="summary" class="evidence-compact-metrics"><button v-for="(c,i) in displayedChains.filter(c=>c.count!=null)" :key="c.id" :style="{'--tone':colors[i]}" @click="chain=c.id"><span>{{c.label}}</span><strong>{{fmt(c.count)}}<small>{{c.id==='fund_paper'?'AI资助关联':'技术样本关联'}}</small></strong></button></div><section class="evidence-process"><div class="study-heading"><h3>证据构建过程</h3><span>从多源成果到技术影响研究</span></div><div class="process-cards"><article v-for="(p,i) in processSteps" :key="p.title"><span class="process-number">{{i+1}}</span><h4>{{p.title}}</h4><p>{{p.text}}</p><footer><small>{{p.sourceLabel}}</small><b>{{p.source}}</b></footer></article></div></section><section ref="graphShell" class="panel evidence-panel"><div class="panel-heading"><h3>交互证据图</h3><div class="graph-actions"><button @click="allLabels=!allLabels">{{allLabels?'收起详细标签':'展开全部标签'}}</button><button @click="chart?.reset()">重置视图</button><button @click="fullScreen">全屏 / 退出</button></div></div><div class="compact-tabs graph-chain-tabs"><button v-for="[id,label] in chainTabs" :key="id" :class="{active:chain===id}" @click="chain=id">{{label}}</button></div><div class="graph-toolbar"><span>{{graph?.meta?.nodes??0}} 节点 · {{graph?.meta?.edges??0}} 条关系</span><span>人工智能 · 关系样本</span></div><div class="graph-layout"><div class="graph-canvas"><div v-if="loading" class="empty-chart">正在读取 {{activeTitle}} …</div><div v-else-if="error" class="empty-chart"><p>{{error}}</p><button class="button" @click="fetchGraph">重试</button></div><Chart v-else-if="graph?.nodes?.length" ref="chart" :option="graphOption" :height="440" @select="onSelect"/><div v-else class="empty-chart"><b>当前范围暂无可展示的已建立关系</b><p>{{scopeLabel}} · {{activeTitle}}</p><p v-if="chain==='fund_paper'&&scope==='llm'">切换 AI 宽口径或前史 / 语境，探索已有关系。</p><p v-if="chain==='fund_patent'">基金—专利关系已接入统一库，本视图展示其中的技术关联样例。</p></div><div class="graph-hint">悬停查看名称 · 拖动节点 · 滚轮缩放 · 点击节点或连线查看证据</div></div><aside class="graph-inspector"><template v-if="selected"><div class="inspector-title"><span class="type-tag">{{selected.kind==='node'?(typeLabels[selected.item.type]||selected.item.type):'关系证据'}}</span><button @click="selected=null" aria-label="关闭节点详情">×</button></div><h4>{{selected.item.label}}</h4><template v-if="selected.kind==='node'"><dl><dt v-if="selected.item.year">年份</dt><dd v-if="selected.item.year">{{selected.item.year}}</dd><dt v-if="selected.item.url">原始文献</dt><dd v-if="selected.item.url"><a :href="safeUrl(selected.item.url)" target="_blank" rel="noopener">查看原文 ↗</a></dd><dt v-if="readableSource(selected.item.source)">来源</dt><dd v-if="readableSource(selected.item.source)">{{selected.item.source}}</dd><template v-for="[k,v] in selectedFields" :key="k"><dt>{{fieldLabels[k]||k}}</dt><dd><a v-if="k==='url'" :href="safeUrl(v)" target="_blank" rel="noopener">查看原文 ↗</a><span v-else>{{display(v)}}</span></dd></template></dl><h5 v-if="neighbors.length">相邻关系 {{neighbors.length}}</h5><button v-for="e in neighbors.slice(0,10)" :key="e.id" class="edge-choice" @click="selected={kind:'edge',item:e}">{{e.label}} →</button></template><template v-else><dl><dt>源节点</dt><dd>{{nodeName(selected.item.source)}}</dd><dt>目标节点</dt><dd>{{nodeName(selected.item.target)}}</dd><dt>关系状态</dt><dd>{{({snippet_reviewed:'题名 / 原文片段已核对',rule_candidate:'关键词规则候选',source_link:'来源项目ID关联',primary_source_checked_demo_seed:'代表论文原文已核对'})[selected.item.status]||selected.item.status}}</dd></dl><div v-for="(e,i) in selected.item.evidence||[]" :key="i" class="graph-evidence"><strong>{{fieldLabels[e.field]||e.field||'原文依据'}}</strong><p>{{e.snippet||(readableSource(e.source)?e.source:'原文依据')}}</p><p v-if="readableSource(e.source)" class="graph-source">{{e.source}}</p><a v-if="e.url" :href="safeUrl(e.url)" target="_blank" rel="noopener">查看依据原文 ↗</a></div></template></template><template v-else><h4>节点与关系详情</h4><p>点击左侧图中的节点或连线，查看来源、匹配字段与原文依据。</p><div class="entity-legend"><span v-for="t in nodeTypes" :key="t"><i :style="{background:typeColor[t]||'#64748b'}"></i>{{typeLabels[t]||t}}</span></div></template></aside></div><p class="chart-note"><b>{{graph?.meta?.scope_label||scopeLabel}}</b> · {{graph?.meta?.sample_records??0}} 条源记录样本</p></section></div></template>